export type SecretMap = Partial<{ [key in string]: string }>
export type ShortcutBinding = { id: string; name: string; description: string; default_binding: string; current_binding: string }
export type SoundTheme = "marimba" | "pop" | "custom"
/**
 * Phase of the streaming overlay card, emitted to drive its UI state.
 */
export type StreamPhase = 
/**
 * Receiving audio / live text (or waiting for the stream to begin). Rust
 * does not emit this today; the frontend starts in this phase and Rust only
 * emits transitions away from it.
 */
"listening" | 
/**
 * Finalizing or post-processing — show a spinner.
 */
"working"
/**
 * Emitted to switch the streaming overlay to a working spinner.
 */
export type StreamPhaseEvent = { phase: StreamPhase; 
/**
 * Present only when `phase` is `Working`.
 */
kind?: StreamWorkKind | null }
/**
 * Live transcription snapshot emitted to the overlay during a streaming run.
 * `committed` is the append-only, flicker-free prefix; `tentative` is the
 * volatile suffix the model may still rewrite.
 */
export type StreamTextEvent = { committed: string; tentative: string }
/**
 * Semantic kind of "working" phase, used to localize the spinner label.
 */
export type StreamWorkKind = "transcribing" | "polishing"
/**
 * Ressource téléchargée au premier résumé. Les deux ne viennent pas du même
 * hébergeur — le moteur de github.com, le modèle de huggingface.co — et un
 * réseau d'entreprise en filtre souvent une sans l'autre : dire laquelle a
 * échoué est la première information utile.
 */
export type SummaryAsset = 
/**
 * Le moteur llama.cpp (quelques dizaines de Mo).
 */
"engine" | 
/**
 * Le modèle GGUF (environ 2 Go).
 */
"model"
/**
 * Erreurs remontées au front, qui les traduit (`settings.file.summary.errors.*`).
 */
export type SummaryError = 
/**
 * Le serveur n'a pas pu être joint : `failure` classe la panne (c'est ce
 * qui décide du conseil affiché), `asset` et `host` disent quoi et où, et
 * `detail` porte la chaîne de causes — affichée repliée, et copiable,
 * pour qu'une capture d'écran du client soit exploitable par le support.
 */
{ kind: "network"; asset: SummaryAsset; failure: NetworkFailure; host: string; detail: string } | { kind: "diskSpace"; neededBytes: number; freeBytes: number } | { kind: "memory"; neededBytes: number; freeBytes: number } | 
/**
 * Le serveur a répondu, mais le fichier n'est pas arrivé complet (statut
 * HTTP inattendu, flux coupé, taille incohérente, écriture impossible).
 */
{ kind: "downloadFailed"; asset: SummaryAsset; host: string; detail: string } | { kind: "checksumMismatch" } | { kind: "engineStartFailed"; detail: string } | { kind: "incompleteOutput" } | { kind: "cancelled" } | 
/**
 * Un résumé est déjà en cours.
 */
{ kind: "busy" }
/**
 * Phase en cours, pour l'encart de progression de l'onglet Fichier.
 */
export type SummaryPhase = 
/**
 * Téléchargement du moteur ; `current` = pourcentage (0-100), `total` = 100.
 */
"engine" | 
/**
 * Téléchargement du modèle ; `current` = pourcentage (0-100), `total` = 100.
 */
"model" | 
/**
 * Démarrage du serveur (chargement du modèle en mémoire) ; 0/1 puis 1/1.
 */
"starting" | 
/**
 * Résumé ; `current` = partie en cours, `total` = nombre de parties.
 */
"summarizing"
/**
 * Événement `summary-progress`, émis à chaque étape (téléchargements,
 * démarrage, tranche en cours).
 */
export type SummaryProgress = { phase: SummaryPhase; current: number; total: number }
/**
 * État des fichiers nécessaires, pour annoncer le téléchargement unique.
 */
export type SummaryStatus = { engineReady: boolean; modelReady: boolean; 
/**
 * Octets restant à télécharger (0 si tout est installé).
 */
downloadSizeBytes: number }
export type TextAsset = { 
/**
 * Nom du fichier importé ; `None` pour un texte collé.
 */
fileName: string | null; content: string; words: number; updatedAt: number; 
/**
 * Skill : `name` et `description` de son en-tête YAML, s'il en a un.
 */
title: string | null; description: string | null }
/**
 * Élément texte du compte rendu : charte éditoriale ou skill.
 */
export type TextAssetKind = "editorial" | "skill"
/**
 * UI appearance mode. `System` follows the OS `prefers-color-scheme`; `Light`
 * and `Dark` force one of the two palettes Handy already ships.
 */
export type Theme = "system" | "light" | "dark"
export type TranscribeAcceleratorSetting = "auto" | "cpu" | "gpu"
export type TypingTool = "auto" | "wtype" | "kwtype" | "dotool" | "ydotool" | "xdotool"
/**
 * Progression du téléchargement de la vidéo d'une entrée d'historique.
 */
export type VideoDownloadProgress = { history_id: number; percent: number }
export type WindowsMicrophonePermissionStatus = { supported: boolean; overall_access: PermissionAccess; device_access: PermissionAccess; app_access: PermissionAccess; desktop_app_access: PermissionAccess }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
